<?php
/** Plugin Name: TEMP PS S1719v — petshop-lenteliu-valymas v1.0: 1 deploy + sausas (kandidatai), 2 pirmas realus valymas, 9 pašalinti */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1719v'])) return; $f=$_GET['ps_s1719v']; $r=['v'=>'S1719v','faze'=>$f]; @set_time_limit(250); global $wpdb; $p=$wpdb->prefix;
  $fp=WP_CONTENT_DIR.'/mu-plugins/petshop-lenteliu-valymas.php'; $code=base64_decode('');
  $size=function($t) use($wpdb,$p){ return $wpdb->get_row($wpdb->prepare("SELECT TABLE_ROWS r,ROUND((DATA_LENGTH+INDEX_LENGTH)/1048576,1) mb FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=%s",$p.$t),ARRAY_A); };
  try{
    if($f==='1'){ token_get_all($code,TOKEN_PARSE); file_put_contents($fp,$code); $r['md5']=md5_file($fp); $hb=wp_remote_get('https://petshop.lt/?ps_hb='.time(),['timeout'=>25,'sslverify'=>false]); $r['hb']=is_wp_error($hb)?'ERR':wp_remote_retrieve_response_code($hb); if($r['hb']!=200){ rename($fp,$fp.'.off_s1719'); throw new Exception('ROLLBACK'); }
      require_once $fp; $r['sausas']=Petshop_Lenteliu_Valymas::vykdyti(true); $r['cron']=wp_next_scheduled('ps_lenteliu_valymas')?date('Y-m-d H:i',wp_next_scheduled('ps_lenteliu_valymas')):null; }
    if($f==='2'){ if(!class_exists('Petshop_Lenteliu_Valymas')) require_once $fp; foreach(['ps_carts','ps_web_ivykiai','ps_sargas_klaidos','woocommerce_sessions'] as $t) $r['pries'][$t]=$size($t); $r['rez']=Petshop_Lenteliu_Valymas::vykdyti(false); foreach(['ps_carts','ps_web_ivykiai','ps_sargas_klaidos','woocommerce_sessions'] as $t){ $wpdb->query("OPTIMIZE TABLE {$p}$t"); $r['po'][$t]=$size($t); } }
    if($f==='9'){ wp_clear_scheduled_hook('ps_lenteliu_valymas'); if(file_exists($fp)) rename($fp,$fp.'.off_s1719'); $r['pasalinta']=!file_exists($fp); }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE); exit;
},1);
